import java.util.*;
import java.io.*;
import java.math.*;

public class Main {
    static final BigInteger MODULUS = new BigInteger("998244353");
    static void displayError() {
        System.out.println(-1);
    }
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);
        String line = reader.readLine();
        int testCases = 1;
        // testCases = Integer.parseInt(line);
        while (testCases-- > 0) {
            line = reader.readLine();
            StringTokenizer tokens = new StringTokenizer(line);
            long n = Long.parseLong(tokens.nextToken());
            long m = Long.parseLong(tokens.nextToken());
            line = reader.readLine();
            tokens = new StringTokenizer(line);
            long l = Long.parseLong(tokens.nextToken());
            long r = Long.parseLong(tokens.nextToken());
            long segmentLength = r - l;
            long evenCount = segmentLength / 2 + 1;
            long oddCount = (segmentLength + 1) / 2;
            if ((n * m) % 2 == 1) {
                BigInteger base = BigInteger.valueOf(segmentLength + 1);
                BigInteger answer = base.modPow(BigInteger.valueOf(n * m), MODULUS);
                writer.println(answer);
            } else {
                BigInteger power1 = BigInteger.valueOf(evenCount + oddCount).modPow(BigInteger.valueOf(n * m), MODULUS);
                BigInteger power2 = BigInteger.valueOf(evenCount - oddCount).modPow(BigInteger.valueOf(n * m), MODULUS);
                BigInteger totalSum = power1.add(power2);
                BigInteger invTwo = BigInteger.valueOf(2).modInverse(MODULUS);
                BigInteger finalResult = totalSum.multiply(invTwo).mod(MODULUS);
                writer.println(finalResult);
            }
        }
        writer.flush();
    }
}
